{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.tuco_kids_FACEBOOK_CONSOLIDATED; CREATE TABLE public.tuco_kids_FACEBOOK_CONSOLIDATED AS SELECT Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, \'FACEBOOK\' AS Account_Name, Account_ID, Campaign_Name, Campaign_ID, CAST(FB.date_start AS date) AS Date, SUM(CLICKS) AS Clicks, SUM(COALESCE(inline_link_clicks, 0)) AS Link_Clicks, SUM(SPEND) AS Spend, SUM(IMPRESSIONS) AS Impressions, SUM(COALESCE(Fc.Conversions, 0)) AS Conversions, SUM(COALESCE(Fcv.Conversion_Value, 0)) AS Conversion_Value, SUM(COALESCE(fd.add_to_carts, 0)) AS Add_to_carts, SUM(COALESCE(fdv.add_to_cart_value, 0)) AS Add_to_cart_value, SUM(COALESCE(fe.landing_page_views, 0)) AS Landing_page_views, SUM(COALESCE(ff.initiate_checkouts, 0)) AS Initiate_checkouts, SUM(COALESCE(ffv.initiate_checkouts_value, 0)) AS Initiate_checkouts_value, \'FACEBOOK\' AS Channel, \'FACEBOOK\' AS Account FROM custom_facebook_marketing_facebook_ads_customcampaigns_data FB LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS Conversions FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fc ON FB.ad_id = Fc.ad_id AND FB.date_start = Fc.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS Conversion_Value FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fcv ON FB.ad_id = Fcv.ad_id AND FB.date_start = Fcv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS add_to_carts FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fd ON FB.ad_id = Fd.ad_id AND FB.date_start = Fd.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS add_to_cart_value FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fdv ON FB.ad_id = Fdv.ad_id AND FB.date_start = Fdv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS landing_page_views FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'landing_page_view\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fe ON FB.ad_id = Fe.ad_id AND FB.date_start = Fe.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS initiate_checkouts FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Ff ON FB.ad_id = Ff.ad_id AND FB.date_start = Ff.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS initiate_checkouts_value FROM custom_facebook_marketing_facebook_ads_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Ffv ON FB.ad_id = Ffv.ad_id AND FB.date_start = Ffv.date_start GROUP BY Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, FB.date_start;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select database, schema, "table" from SVV_TABLE_INFO limit 1
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            